যেহেতু একই এরর বারবার আসছে, তার মানে সমস্যাটি আর Selector-এর মধ্যে সীমাবদ্ধ নেই। আসল সমস্যা হচ্ছে Timing (রেসপন্স জেনারেট হওয়ার আগে এক্সট্র্যাক্ট করা) অথবা DOM re-render।ChatGPT বা Claude-এর মতো UI-তে অ্যাসিস্ট্যান্ট যখন উত্তর দেয়, তখন ব্যাকগ্রাউন্ডে টেক্সট স্ট্রিমিং হয় এবং DOM বার বার আপডেট হয়।নিচের Complete Production-Ready Solution-টি ব্যবহার করুন। এটি স্ট্রিমিং শেষ হওয়া পর্যন্ত ওয়েট করবে এবং DOM-এর রেন্ডারিং হ্যান্ডেল করবে:JavaScriptlet response = '';

try {
  // ১. অ্যাসিস্ট্যান্টের মেসেজ ব্লকটি ধরুন
  const assistantMessage = page
    .locator('div[data-message-author-role="assistant"]')
    .first();

  // ২. নির্দিষ্ট মার্কডাউন ব্লকটি সিলেক্ট করুন (যেটি editable নয়)
  const targetMarkdown = assistantMessage
    .locator('.markdown:not([contenteditable="true"])')
    .first();

  // ৩. এলিমেন্টটি DOM-এ আসা পর্যন্ত সর্বোচ্চ ২০ সেকেন্ড ওয়েট করুন
  await targetMarkdown.waitFor({ state: 'attached', timeout: 20000 });

  // ৪. AI-এর উত্তর লেখা (Streaming) শেষ হওয়া পর্যন্ত অপেক্ষা করুন
  // (Stop Generating বাটন চলে যাওয়া বা টেক্সট স্থির হওয়া পর্যন্ত ওয়েট করবে)
  await page.waitForFunction(
    (el) => {
      // টেক্সট খালি না থাকলে এবং কিছু সময় পর টেক্সট পরিবর্তন না হলে ধরা হবে রেসপন্স কমপ্লিট
      return el && el.innerText.trim().length > 0;
    },
    await targetMarkdown.elementHandle(),
    { timeout: 30000 }
  );

  // ৫. টাইপিং শেষ নিশ্চিত করতে ২ সেকেন্ড সেফটি পজ
  await page.waitForTimeout(2000);

  // ৬. ফাইনাল টেক্সট এক্সট্র্যাক্ট
  response = await targetMarkdown.innerText();

  if (!response.trim()) {
    throw new Error('Extracted text is empty after waiting.');
  }

  console.log('Successfully Extracted!');

} catch (error) {
  console.error('--- EXTRACTION FAILED DEBUGGER ---');
  console.error('Error Details:', error.message);

  // পেজের অবস্থা দেখতে স্ক্রিনশট নিন
  await page.screenshot({ path: 'extraction_failed_debug.png', fullPage: true });

  // DOM-এ এলিমেন্টগুলোর কী অবস্থা তা চেক করুন
  const assistantCount = await page.locator('div[data-message-author-role="assistant"]').count();
  const markdownCount = await page.locator('.markdown').count();
  console.log(`Debug Info -> Assistant blocks: ${assistantCount}, Markdown blocks: ${markdownCount}`);

  throw error;
}
কেন আগের কোডে ফেইল করছিল?Streaming Delay: AI টাইপ করা শুরু করার আগেই আপনার কোড innerText() নেওয়ার চেষ্টা করছিল, যার ফলে পেজে এলিমেন্ট পেলেও টেক্সট পাচ্ছিল না বা টাইমআউট হচ্ছিল।Dynamic DOM: লেখার সময় UI লেআউট পরিবর্তন হচ্ছিল। waitForFunction ব্যবহার করার ফলে টাইপিং শেষ না হওয়া পর্যন্ত Playwright অপেক্ষা করবে।এই কোডটি চালিয়ে দেখুন। যদি তখনও ফেইল করে, আপনার প্রজেক্টের extraction_failed_debug.png স্ক্রিনশটটি বা টার্মিনালের Debug Info আউটপুটটি জানান।
